Step.StepText:
Set Variable [ $clientFolder; Value:Let ( [
  ~p = While ( [ p = Trim ( $filePath ) ] ; Length ( p ) > 3 and Right ( p ; 1 ) = Char ( 92 ) ; [ p = Left ( p ; Length ( p ) - 1 ) ] ; p ) ;
  ~s = Char ( 92 ) & "Session Notes"
] ;
  If ( Right ( ~p ; Length ( ~s ) ) = ~s ; Left ( ~p ; Length ( ~p ) - Length ( ~s ) ) ; ~p )
) ]

